#!/usr/bin/env node
/**
 * clean-sessions — identify & optionally clean auto-generated duplicate sessions.
 *
 * Usage:
 *   node scripts/clean-sessions.js              # preview only (dry-run)
 *   node scripts/clean-sessions.js --clean      # move dupes to .claude/archived-sessions/
 *   node scripts/clean-sessions.js --delete     # permanently delete dupes
 *   node scripts/clean-sessions.js --stats      # show session statistics
 *   node scripts/clean-sessions.js --all        # scan all projects (like csessions --all)
 *
 * Auto-generated patterns it detects:
 *   - "Analyze this codebase for security vulnerabilities"
 *   - "Analyze this codebase for performance optimizations"
 *   - "Analyze test coverage and identify gaps"
 *   - Startup / hook-only sessions (no user message)
 *   - Mem-observer / knowledge-agent sessions
 */
'use strict';

const fs = require('fs');
const path = require('path');
const os = require('os');

// ── Ansi ─────────────────────────────────────────────────────────
const tty = process.stdout.isTTY;
const esc = (n, s) => tty ? `\x1b[${n}${s}\x1b[0m` : s;
const R = s => esc('31m', s);
const G = s => esc('32m', s);
const Y = s => esc('33m', s);
const C = s => esc('36m', s);
const B = s => esc('1m', s);
const D = s => esc('2m', s);

// ── Auto-generated patterns ──────────────────────────────────────
const AUTO_PATTERNS = [
  /^Analyze this codebase for security vulnerabilities/i,
  /^Analyze this codebase for performance optimizations/i,
  /^Analyze test coverage and identify gaps/i,
  /^(You are a Claude-Mem|Hello memory agent|claude-mem|knowledge-agent)/i,
];

const isAutoGenerated = label =>
  AUTO_PATTERNS.some(p => p.test(label)) || !label || label === '(no content)';

// ── Path helpers ─────────────────────────────────────────────────
const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
const home = os.homedir();

function findBases() {
  const dirs = [];
  const seen = new Set();
  const add = d => { if (d && fs.existsSync(d) && !seen.has(d)) { seen.add(d); dirs.push(d); } };
  add(path.join(home, '.claude', 'projects'));
  if (process.platform === 'linux') {
    try {
      for (const u of fs.readdirSync('/home')) add(path.join('/home', u, '.claude', 'projects'));
      add('/root/.claude/projects');
    } catch {}
  }
  return dirs;
}

const encodePath = p => p.replace(/[^a-zA-Z0-9]/g, '-');

function findProjectDir(cwd) {
  const enc = encodePath(cwd);
  for (const base of findBases()) {
    const c = path.join(base, enc);
    if (fs.existsSync(c)) return c;
  }
  return null;
}

// ── Read session label from JSONL ────────────────────────────────
function getSessionLabel(fp) {
  try {
    const raw = fs.readFileSync(fp, { encoding: 'utf-8' });
    for (const line of raw.split('\n')) {
      if (!line.trim()) continue;
      try {
        const d = JSON.parse(line);
        const content = d.content;
        if (Array.isArray(content)) {
          for (const c of content) {
            if (c?.type === 'text' && c.text?.trim().length > 30) return c.text.trim();
          }
        } else if (typeof content === 'string' && content.trim().length > 30) {
          return content.trim();
        }
        if (d.lastPrompt?.trim().length > 30) return d.lastPrompt.trim();
      } catch {}
    }
    // Check sessions-index.json for a summary
    const dir = path.dirname(fp);
    const idxFile = path.join(dir, 'sessions-index.json');
    if (fs.existsSync(idxFile)) {
      const idx = JSON.parse(fs.readFileSync(idxFile, 'utf-8'));
      const sid = path.basename(fp, '.jsonl');
      const entry = idx.sessions?.[sid] || idx[sid];
      if (entry?.name) return entry.name;
      if (entry?.summary) return entry.summary;
    }
  } catch {}
  return '';
}

// ── Collect sessions from a project dir ──────────────────────────
function collectSessions(projDir) {
  const proj = path.basename(projDir);
  let files;
  try { files = fs.readdirSync(projDir); } catch { return []; }
  return files
    .filter(f => f.endsWith('.jsonl'))
    .map(f => ({ name: f, sid: f.slice(0, -6) }))
    .filter(f => UUID_RE.test(f.sid))
    .map(f => {
      const fp = path.join(projDir, f.name);
      const st = fs.statSync(fp, { throwIfNoEntry: false });
      return st ? { ...f, mtime: st.mtimeMs, path: fp, size: st.size } : null;
    })
    .filter(Boolean)
    .sort((a, b) => b.mtime - a.mtime)
    .map(f => {
      let label = getSessionLabel(f.path);
      return { ...f, label, proj, isAuto: isAutoGenerated(label) };
    });
}

// ── Human time ───────────────────────────────────────────────────
const timeAgo = ms => {
  const d = Math.floor((Date.now() - ms) / 1000);
  if (d < 0) return 'now';
  if (d < 60) return `${d}s`;
  if (d < 3600) return `${Math.floor(d / 60)}m`;
  if (d < 86400) return `${Math.floor(d / 3600)}h ${Math.floor((d % 3600) / 60)}m`;
  return `${Math.floor(d / 86400)}d`;
};

// ── Actions ──────────────────────────────────────────────────────
function archiveSessions(sessions, archiveDir) {
  fs.mkdirSync(archiveDir, { recursive: true });
  let count = 0;
  for (const s of sessions) {
    const dest = path.join(archiveDir, s.name);
    try {
      fs.renameSync(s.path, dest);
      count++;
    } catch (err) {
      console.error(R(`  ✗ Failed to archive ${s.name}: ${err.message}`));
    }
  }
  return count;
}

function deleteSessions(sessions) {
  let count = 0;
  for (const s of sessions) {
    try {
      fs.unlinkSync(s.path);
      count++;
    } catch (err) {
      console.error(R(`  ✗ Failed to delete ${s.name}: ${err.message}`));
    }
  }
  return count;
}

// ── Main ─────────────────────────────────────────────────────────
function main() {
  const args = process.argv.slice(2);
  const flags = {
    clean: args.includes('--clean'),
    delete: args.includes('--delete'),
    stats: args.includes('--stats'),
    all: args.includes('--all'),
  };

  // Resolve project directory
  let sessions = [];
  const bases = findBases();

  if (flags.all) {
    for (const base of bases) {
      let dirs;
      try { dirs = fs.readdirSync(base); } catch { continue; }
      for (const d of dirs) {
        const fp = path.join(base, d);
        if (fs.statSync(fp, { throwIfNoEntry: false })?.isDirectory()) {
          sessions.push(...collectSessions(fp));
        }
      }
    }
  } else {
    const cwd = process.cwd();
    const projDir = findProjectDir(cwd);
    if (!projDir) {
      console.log(R('No session directory found for current project.'));
      process.exit(1);
    }
    sessions = collectSessions(projDir);
  }

  const total = sessions.length;
  const auto = sessions.filter(s => s.isAuto);
  const user = sessions.filter(s => !s.isAuto);

  // ── Stats mode ─────────────────────────────────────────────────
  if (flags.stats) {
    const totalSize = sessions.reduce((a, s) => a + s.size, 0);
    const autoSize = auto.reduce((a, s) => a + s.size, 0);
    console.log(B('Session Statistics\n'));
    console.log(`  ${C('Total sessions:')}       ${total}`);
    console.log(`  ${C('User sessions:')}         ${G(user.length)}`);
    console.log(`  ${C('Auto-generated:')}        ${Y(auto.length)}  (${(autoSize / 1024 / 1024).toFixed(1)} MB / ${(totalSize / 1024 / 1024).toFixed(1)} MB)`);
    console.log(`  ${C('Empty/no-content:')}      ${Y(sessions.filter(s => !s.label).length)}`);

    // Breakdown by pattern
    console.log(D('\nAuto-generated breakdown:'));
    const counts = {};
    for (const s of auto) {
      const key = s.label ? s.label.split(':')[0].split('\n')[0].slice(0, 60) : '(empty)';
      counts[key] = (counts[key] || 0) + 1;
    }
    for (const [pattern, count] of Object.entries(counts).sort((a, b) => b[1] - a[1])) {
      console.log(`    ${Y(String(count).padStart(3))}  ${pattern}`);
    }
    return;
  }

  // ── Clean / Delete mode ────────────────────────────────────────
  if (flags.clean || flags.delete) {
    if (auto.length === 0) {
      console.log(G('✓ No auto-generated sessions to clean.'));
      return;
    }

    const action = flags.delete ? 'Deleted' : 'Archived';
    const count = flags.delete
      ? deleteSessions(auto)
      : archiveSessions(auto, path.join(home, '.claude', 'archived-sessions'));

    console.log(G(`✓ ${action} ${count} auto-generated session(s)`));
    console.log(D(`  Kept ${user.length} user session(s)`));
    return;
  }

  // ── Default: preview mode ──────────────────────────────────────
  console.log(B('Session Overview'));
  console.log(D(`  ${total} total · ${G(String(user.length))} user · ${Y(String(auto.length))} auto-generated\n`));

  // Print user sessions
  if (user.length) {
    console.log(B(G('User Sessions:')));
    user.forEach((s, i) => {
      const num = String(i + 1).padStart(3);
      const lbl = (s.label.slice(0, 75) || '(empty)').padEnd(75);
      const hint = flags.all ? D(` [${s.proj}]`) : '';
      console.log(`  ${C(num)}  ${lbl}${hint}`);
      console.log(`       ${D(`${s.sid}  •  ${timeAgo(s.mtime)}`)}`);
    });
    console.log();
  }

  // Print auto-generated sessions grouped
  if (auto.length) {
    console.log(B(Y('Auto-Generated (use --clean to archive):')));

    // Group by pattern
    const groups = {};
    for (const s of auto) {
      const key = s.label ? s.label.split(':')[0].split('\n')[0].slice(0, 60) : '(empty / startup)';
      if (!groups[key]) groups[key] = [];
      groups[key].push(s);
    }

    for (const [pattern, items] of Object.entries(groups)) {
      const count = items.length;
      const first = items[0];
      const last = items[items.length - 1];
      const totalSize = items.reduce((a, s) => a + s.size, 0);
      console.log(`  ${Y(String(count).padStart(2))}×  ${D(pattern)}`);
      console.log(`       ${D(`~${((last.mtime - first.mtime) / 3600000).toFixed(1)}h span  •  ${(totalSize / 1024 / 1024).toFixed(1)} MB`)}`);
    }
    console.log();
  }

  // Tip
  console.log(D(`Tip: run ${B('node scripts/clean-sessions.js --clean')} to archive duplicates, or ${B('--delete')} to remove permanently.`));
  console.log(D(`     ${B('--stats')} for detailed breakdown.`));
}

if (require.main === module) main();
